  /// <summary>Danh sach nut hien thi tren palette cua host dang chay.</summary>
  internal static TgToolInfo[] ForHost(string host) {
    var list = new System.Collections.Generic.List<TgToolInfo>();
    foreach (var t in All) if (t.IsTool && t.Supports(host) && LoadSettingsStore.IsEnabled(t.Id)) list.Add(t);
    list.Sort(delegate(TgToolInfo a, TgToolInfo b) { return a.Order.CompareTo(b.Order); });
    return list.ToArray();
  }

  /// <summary>Cac nut cua mot nhom tren palette.</summary>
  internal static TgToolInfo[] ForGroup(string host, string groupKey) {
    var list = new System.Collections.Generic.List<TgToolInfo>();
    foreach (var t in ForHost(host)) if (t.GroupKey == groupKey) list.Add(t);
    return list.ToArray();
  }

  /// <summary>Thu tu nhom dung theo khai bao "groups" trong tools.json.</summary>
  internal static string[] GroupKeys(string host) {
    var keys = new System.Collections.Generic.List<string>();
    foreach (var t in ForHost(host)) if (t.GroupKey != null && !keys.Contains(t.GroupKey)) keys.Add(t.GroupKey);
    return keys.ToArray();
  }

